package br.com.minhagibiteca.catalog.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="creators") public class Creator { @Id private UUID id; @Column(name="owner_user_id",nullable=false) private UUID ownerUserId; @Column(nullable=false) private String name; @Column(name="normalized_name",nullable=false) private String normalizedName; @Column(name="sort_name") private String sortName; @Column(name="created_at") private Instant createdAt; protected Creator(){} public static Creator create(UUID owner,String name){Creator c=new Creator();c.id=UUID.randomUUID();c.ownerUserId=owner;c.name=name.trim();c.normalizedName=c.name.toLowerCase(Locale.ROOT);c.createdAt=Instant.now();return c;} public UUID getId(){return id;} public UUID getOwnerUserId(){return ownerUserId;} public String getName(){return name;} }
